// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/kit/EventTitle.tsx. Edit it there, then run `npm run sync:film`.
import React, { createContext, useContext } from "react";
import { useCurrentFrame } from "remotion";
import { palette } from "../theme/palette";
import { fonts, isDevanagari } from "../theme/fonts";
import { bi, type Bi } from "../data/i18n";
import { EASE, prog } from "./motion";

type Text = string | Bi;

/** Print pages set this so a frozen scene shows its artwork without its own title block. */
export const HideEventTitles = createContext(false);
const asBi = (t: Text): Bi => (typeof t === "string" ? (isDevanagari(t) ? { hi: t, en: "" } : bi(t)) : t);

/**
 * Bilingual event typography, revealed in stages:
 *   divider draws → tagline (Hindi · English) → title (Hindi, English beneath; centre-out mask)
 *   → detail lines (each Hindi with its English beneath).
 * Pass English strings and they are translated through hindi.txt, or pass {hi, en} directly.
 * `top` is where the block would have started in the English-only layout; the block grows
 * upward to fit the English companions and never runs past the bottom of the frame.
 */
export const EventTitle: React.FC<{
  start?: number;
  kicker?: Text;
  title: Text;
  lines?: Text[];
  top: number;
  left?: number;
  width?: number;
  theme?: "dark" | "light";
  titleSize?: number;
  plaque?: boolean;
  exitAt?: number;
}> = ({ start = 0, kicker, title, lines = [], top, left = 0, width = 1080, theme = "dark", titleSize = 104, plaque, exitAt }) => {
  const hidden = useContext(HideEventTitles);
  const f = useCurrentFrame() - start;
  const out = exitAt !== undefined ? 1 - prog(f + start, exitAt, 16, EASE.in) : 1;
  const colors =
    theme === "dark"
      ? { kicker: palette.goldDeep, title: palette.maroon, line: palette.ink, rule: palette.gold }
      : { kicker: palette.goldLight, title: palette.ivoryLight, line: palette.ivory, rule: palette.goldLight };
  const K = kicker ? asBi(kicker) : undefined;
  const T = asBi(title);
  // Details (date · time · venue) merge into ONE Hindi line and ONE English line — compact and calm.
  const parts = lines.map(asBi).filter((l) => l.hi || l.en);
  const L: Bi[] = parts.length
    ? [{ hi: parts.map((p) => p.hi).filter(Boolean).join("  ·  "), en: parts.map((p) => p.en).filter(Boolean).join("  ·  ") }]
    : [];

  const hiTitle = Math.round(titleSize * 0.8);
  const enTitle = Math.round(titleSize * 0.36);
  const hiLine = 33;
  const enLine = 27;
  const est = (K ? 44 : 0) + hiTitle * 1.3 + (T.en ? enTitle * 1.2 : 0) + 42 + L.reduce((h, l) => h + (l.hi ? hiLine * 1.35 * (l.hi.length > 46 ? 2 : 1) : 0) + (l.en ? enLine * 1.2 * (l.en.length > 64 ? 2 : 1) + 2 : 0), 0);
  // Sit the block on the bottom margin (never higher than needed, never past the frame).
  const y = Math.max(Math.min(top, 1860 - est), 1860 - est - 40);

  const rule = prog(f, 0, 22, EASE.cine);
  const k = prog(f, 6, 20);
  const t = prog(f, 12, 30, EASE.cine);

  if (hidden) return null;
  return (
    <div style={{ position: "absolute", top: y, left, width, display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", opacity: out }}>
      {plaque ? (
        <div
          style={{
            position: "absolute",
            inset: "-34px 70px -30px",
            borderRadius: 28,
            background: "radial-gradient(ellipse at center, rgba(251,246,236,0.92) 45%, rgba(251,246,236,0) 74%)",
            opacity: prog(f, 0, 20),
          }}
        />
      ) : null}
      {K ? (
        <div
          style={{
            position: "relative",
            color: colors.kicker,
            opacity: k,
            transform: `translateY(${(1 - k) * 10}px)`,
            whiteSpace: "nowrap",
            padding: "2px 22px 4px",
            borderRadius: 999,
            // A soft ribbon behind the tagline so it reads over any artwork.
            background: theme === "dark" ? "rgba(251,246,236,0.9)" : "rgba(36,16,30,0.55)",
            boxShadow: theme === "dark" ? "0 0 0 1px rgba(180,138,69,0.35)" : "0 0 0 1px rgba(221,190,124,0.35)",
          }}
        >
          <span style={{ fontFamily: fonts.label, fontSize: 28 }}>{K.hi}</span>
          {K.en ? (
            <span style={{ fontFamily: fonts.latin, fontStyle: "italic", fontSize: 25, opacity: 0.88 }}>
              {"  ·  "}
              {K.en}
            </span>
          ) : null}
        </div>
      ) : null}
      <div style={{ position: "relative", clipPath: `inset(-40% ${(1 - t) * 50}% -40% ${(1 - t) * 50}%)`, marginTop: 2 }}>
        <div style={{ fontFamily: fonts.display, fontWeight: 600, fontSize: hiTitle, lineHeight: 1.3, color: colors.title }}>{T.hi}</div>
        {T.en ? (
          <div style={{ fontFamily: fonts.latin, fontStyle: "italic", fontWeight: 500, fontSize: enTitle, lineHeight: 1.1, color: colors.title, opacity: 0.8 }}>{T.en}</div>
        ) : null}
      </div>
      <svg width={320} height={22} viewBox="0 0 320 22" style={{ position: "relative", margin: "8px 0 10px" }}>
        {rule > 0.001 ? <path d={`M${142 - rule * 132} 11 H142 M178 11 H${178 + rule * 132}`} stroke={colors.rule} strokeWidth={1.3} /> : null}
        <path d="M160 2 L169 11 L160 20 L151 11 Z" fill="url(#foil)" opacity={rule} transform={`rotate(${(1 - rule) * 90} 160 11)`} />
      </svg>
      {L.map((l, i) => {
        const li = prog(f, 30 + i * 8, 22);
        return (
          <div key={i} style={{ position: "relative", maxWidth: 960, opacity: li, transform: `translateY(${(1 - li) * 14}px)`, marginTop: i === 0 ? 0 : 8 }}>
            {l.hi ? <div style={{ fontFamily: fonts.display, fontSize: hiLine, lineHeight: 1.35, color: colors.line }}>{l.hi}</div> : null}
            {l.en ? (
              <div style={{ fontFamily: fonts.latin, fontStyle: "italic", fontSize: enLine, lineHeight: 1.2, color: colors.line, opacity: 0.78, marginTop: 2 }}>{l.en}</div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
};
